package app.studyhub.domain;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="courses") public class Course { @Id @GeneratedValue private UUID id; @Column(nullable=false) private String title; private String description; private String professor; private String university; private String platform; private LocalDate startDate; private LocalDate endDate; @Enumerated(EnumType.STRING) private CourseStatus status=CourseStatus.NOT_STARTED; private String color="#6750E0"; private String icon; public UUID getId(){return id;} public String getTitle(){return title;} public void setTitle(String title){this.title=title;} public String getProfessor(){return professor;} public void setProfessor(String professor){this.professor=professor;} public CourseStatus getStatus(){return status;} public void setStatus(CourseStatus status){this.status=status;} }
